'use client'

import { useEffect, useState } from 'react';

export default function Home() {
    const [status, setStatus] = useState('idle');
    const [task, setTask] = useState('รอรับคำสั่ง...');

    useEffect(() => {
        const fetchStatus = async () => {
            const res = await fetch('/api/status');
            const data = await res.json();
            setStatus(data.status);
            setTask(data.task);
        };

        const intervalId = setInterval(fetchStatus, 1000);
        return () => clearInterval(intervalId);
    }, []);

    let emoji;
    let message;
    const animationClass = status === 'working' ? 'animate-pulse' : '';

    if (status === 'idle') {
        emoji = '😴';
        message = 'กำลังพักผ่อน...';
    } else if (status === 'working') {
        emoji = '💻🔥';
        message = task;
    } else if (status === 'success') {
        emoji = '✅🎉';
        message = 'งานเสร็จสมบูรณ์!';
    }

    return (
        <div className="flex items-center justify-center h-screen bg-gray-800">
            <div className="p-10 border-4 border-gray-600 rounded-lg bg-gray-900">
                <div className={`text-5xl ${animationClass}`}>{emoji}</div>
                <p className="text-white text-xl mt-4">{message}</p>
            </div>
        </div>
    );
}